const STATUS = ['Todas', 'Programada', 'En tránsito', 'Retrasada', 'Detenida', 'Completada']
const FILTER_DEFAULTS = { status:'Todas', carrier:'Todos', vehicle:'Todos', hub:'Lima · Centro', client:'Todos', zone:'Nacional', driver:'Todos', date:'Hoy' }
const chartHourly = [{h:'06',hoy:4,promedio:3},{h:'08',hoy:12,promedio:9},{h:'10',hoy:21,promedio:17},{h:'12',hoy:29,promedio:23},{h:'14',hoy:27,promedio:25},{h:'16',hoy:34,promedio:29},{h:'18',hoy:19,promedio:21}]
