const toneClass = {
  sky:'border-sky-400/20 bg-sky-400/10 text-sky-300', emerald:'border-emerald-400/20 bg-emerald-400/10 text-emerald-300', violet:'border-violet-400/20 bg-violet-400/10 text-violet-300', rose:'border-rose-400/20 bg-rose-400/10 text-rose-300', amber:'border-amber-400/20 bg-amber-400/10 text-amber-300', cyan:'border-cyan-400/20 bg-cyan-400/10 text-cyan-300', slate:'border-white/10 bg-white/5 text-slate-300',
}
const statusTone = { 'En tránsito':'sky', Retrasada:'rose', Detenida:'amber', Programada:'slate', Completada:'emerald' }
const riskTone = { Crítico:'rose', Riesgo:'amber', Normal:'emerald' }

function cx(...values) { return values.filter(Boolean).join(' ') }
function Chip({ tone = 'slate', children, className = '' }) { return <span className={cx('inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs font-semibold', toneClass[tone], className)}>{children}</span> }
function IconButton({ label, children, className = '', ...props }) { return <button type="button" aria-label={label} title={label} className={cx('inline-flex size-10 items-center justify-center rounded-xl text-slate-400 transition hover:bg-white/8 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400', className)} {...props}>{children}</button> }
function Button({ children, variant = 'secondary', className = '', style, ...props }) { const styles = { primary:'bg-sky-400 text-slate-950 hover:bg-sky-300', secondary:'border border-white/10 bg-white/5 text-slate-200 hover:bg-white/10', ghost:'text-slate-400 hover:bg-white/7 hover:text-white', danger:'bg-rose-500 text-white hover:bg-rose-400' }; const fixedTone = variant === 'primary' ? { backgroundColor:'#38bdf8', color:'#09111f' } : variant === 'danger' ? { backgroundColor:'#f43f5e', color:'#fff' } : undefined; return <button type="button" style={{ ...fixedTone, ...style }} className={cx('inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400 disabled:cursor-not-allowed disabled:opacity-50', styles[variant], className)} {...props}>{children}</button> }
function StatusBadge({ status }) { return <Chip tone={statusTone[status] || 'slate'}><span className={cx('size-1.5 rounded-full', statusTone[status] === 'rose' ? 'bg-rose-300' : statusTone[status] === 'amber' ? 'bg-amber-300' : statusTone[status] === 'emerald' ? 'bg-emerald-300' : 'bg-sky-300')} />{status}</Chip> }
function Progress({ value, tone = 'sky', label = true }) { const color = { sky:'bg-sky-400', emerald:'bg-emerald-400', amber:'bg-amber-400', rose:'bg-rose-400', violet:'bg-violet-400' }[tone]; return <div className="min-w-[92px]"><div className="mb-1 flex justify-between text-xs text-slate-400">{label && <span>{value}%</span>}</div><div className="h-1.5 overflow-hidden rounded-full bg-white/8"><div className={cx('h-full rounded-full', color)} style={{ width:`${value}%` }} /></div></div> }

function App() {
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [filterOpen, setFilterOpen] = useState(false)
  const [filters, setFilters] = useState(FILTER_DEFAULTS)
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState([])
  const [sort, setSort] = useState({ key:'id', direction:'desc' })
  const [page, setPage] = useState(1)
  const [density, setDensity] = useState('comfortable')
  const [expanded, setExpanded] = useState(null)
  const [trip, setTrip] = useState(null)
  const [drawerTab, setDrawerTab] = useState('Resumen')
  const [modal, setModal] = useState(null)
  const [formDirty, setFormDirty] = useState(false)
  const [confirm, setConfirm] = useState(null)
  const [lightbox, setLightbox] = useState(null)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [commandOpen, setCommandOpen] = useState(false)
  const [commandQuery, setCommandQuery] = useState('')
  const [scenario, setScenario] = useState('live')
  const [scenarioMenu, setScenarioMenu] = useState(false)
  const [columnsOpen, setColumnsOpen] = useState(false)
  const [visibleColumns, setVisibleColumns] = useState({ carrier:true, cost:true, sla:true, incidents:true })

  useEffect(() => {
    const onKey = event => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setCommandOpen(true) }
      if (event.key === 'Escape') { setCommandOpen(false); setNotificationsOpen(false); setColumnsOpen(false) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  const filtered = useMemo(() => TRIPS.filter(item => {
    const term = query.trim().toLocaleLowerCase()
    const haystack = `${item.id} ${item.origin} ${item.destination} ${item.vehicle} ${item.driver} ${item.carrier}`.toLocaleLowerCase()
    return (!term || haystack.includes(term)) && (filters.status === 'Todas' || item.status === filters.status) && (filters.carrier === 'Todos' || item.carrier === filters.carrier) && (filters.driver === 'Todos' || item.driver === filters.driver)
  }).sort((a,b) => `${a[sort.key]}`.localeCompare(`${b[sort.key]}`, 'es', { numeric:true }) * (sort.direction === 'asc' ? 1 : -1)), [filters, query, sort])
  const pageSize = 5
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const rows = filtered.slice((page - 1) * pageSize, page * pageSize)
  const filterChips = Object.entries(filters).filter(([key,value]) => value !== FILTER_DEFAULTS[key]).map(([key,value]) => ({ key, value }))
  const scenarioCopy = { live:['En vivo', 'Los datos se actualizan automáticamente'], loading:['Actualizando datos', 'Cargando el último estado operativo'], error:['Error de actualización', 'No pudimos cargar algunas rutas'], offline:['Sin conexión', 'Mostrando datos sincronizados a las 14:32:18'] }[scenario]
  const openTrip = item => { setDrawerTab('Resumen'); setTrip(item) }
  const requestClose = target => formDirty ? setConfirm({ type:'discard', target }) : setModal(null)
  const openModal = name => { setFormDirty(false); setModal(name) }
  const applyAction = message => toast.success(message, { duration:3200 })
  const toggleSort = key => setSort(current => current.key === key ? { key, direction:current.direction === 'asc' ? 'desc' : 'asc' } : { key, direction:'asc' })
  const toggleSelected = id => setSelected(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id])
  const toggleAll = () => setSelected(current => rows.every(item => current.includes(item.id)) ? current.filter(id => !rows.some(item => item.id === id)) : [...new Set([...current, ...rows.map(item => item.id)])])
  const updateFilter = (key,value) => { setFilters(current => ({ ...current, [key]:value })); setPage(1) }
  const clearFilters = () => { setFilters(FILTER_DEFAULTS); setQuery(''); setPage(1) }

  return <div className="min-h-screen bg-[#09111f] text-slate-100 selection:bg-sky-300 selection:text-slate-950">
    <Topbar scenario={scenario} scenarioCopy={scenarioCopy} menuOpen={scenarioMenu} setMenuOpen={setScenarioMenu} onScenario={setScenario} notificationsOpen={notificationsOpen} setNotificationsOpen={setNotificationsOpen} onCommand={() => setCommandOpen(true)} onMenu={() => setSidebarOpen(true)} />
    <div className="tct-layout grid min-h-[calc(100vh-73px)] grid-cols-1 xl:grid-cols-[248px_minmax(0,1fr)]">
      <Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <main className="tct-main min-w-0 px-4 py-6 sm:px-6 lg:px-8 xl:px-10 2xl:px-12">
        {scenario === 'loading' ? <LoadingState /> : scenario === 'error' ? <ErrorState onRetry={() => setScenario('live')} /> : <>
          {scenario === 'offline' && <OfflineNotice onRetry={() => setScenario('live')} />}
          <PageHeading onCreate={() => applyAction('Viaje creado como borrador.')} onOptimize={() => setConfirm({ type:'optimize' })} />
          <FilterBar open={filterOpen} setOpen={setFilterOpen} filters={filters} updateFilter={updateFilter} query={query} setQuery={setQuery} chips={filterChips} removeChip={key => updateFilter(key, FILTER_DEFAULTS[key])} clearFilters={clearFilters} />
          <CriticalStrip onOpen={() => openTrip(TRIPS[1])} onIncidence={() => openModal('incidence')} />
          <KpiGrid />
          <section className="tct-hero mt-6 grid gap-5 2xl:grid-cols-[minmax(0,1.58fr)_minmax(350px,.72fr)]">
            <OperationalMap onOpen={openTrip} onIncident={() => openModal('incidence')} />
            <AlertsPanel onOpen={openTrip} onIncident={() => openModal('incidence')} />
          </section>
          <AnalyticsSection />
          <RoutesTable rows={rows} total={filtered.length} page={page} totalPages={totalPages} setPage={setPage} sort={sort} onSort={toggleSort} selected={selected} toggleSelected={toggleSelected} toggleAll={toggleAll} expanded={expanded} setExpanded={setExpanded} openTrip={openTrip} openModal={openModal} density={density} setDensity={setDensity} columnsOpen={columnsOpen} setColumnsOpen={setColumnsOpen} visibleColumns={visibleColumns} setVisibleColumns={setVisibleColumns} clearFilters={clearFilters} />
        </>}
      </main>
    </div>
    {trip && <TripDrawer trip={trip} tab={drawerTab} setTab={setDrawerTab} onClose={() => setTrip(null)} onIncidence={() => openModal('incidence')} onReplan={() => openModal('replan')} onLightbox={setLightbox} />}
    {modal === 'incidence' && <IncidenceModal onDirty={setFormDirty} onClose={() => requestClose('incidence')} onSubmit={() => { setModal(null); setFormDirty(false); applyAction('Incidencia reportada y enviada al centro de operaciones.') }} />}
    {modal === 'replan' && <ReplanModal onDirty={setFormDirty} onClose={() => requestClose('replan')} onSubmit={() => { setModal(null); setFormDirty(false); applyAction('Ruta reprogramada. Se notificará a 8 entregas afectadas.') }} />}
    {confirm && <ConfirmDialog item={confirm} onCancel={() => setConfirm(null)} onConfirm={() => { if (confirm.type === 'discard') { setModal(null); setFormDirty(false); setConfirm(null) } else { setConfirm(null); applyAction('Propuesta de optimización aplicada tras confirmación humana.') } }} />}
    {lightbox !== null && <Lightbox index={lightbox} onClose={() => setLightbox(null)} onChange={setLightbox} />}
    {commandOpen && <CommandPalette query={commandQuery} setQuery={setCommandQuery} onClose={() => setCommandOpen(false)} onOpenTrip={item => { setCommandOpen(false); openTrip(item) }} onIncidence={() => { setCommandOpen(false); openModal('incidence') }} />}
    <Toaster position="bottom-right" toastOptions={{ style:{ background:'#172235', color:'#e2e8f0', border:'1px solid rgba(255,255,255,.12)', padding:'14px 16px' } }} />
  </div>
}

function Topbar({ scenario, scenarioCopy, menuOpen, setMenuOpen, onScenario, notificationsOpen, setNotificationsOpen, onCommand, onMenu }) {
  return <header className="sticky top-0 z-40 border-b border-white/8 bg-[#0d1626]/95 backdrop-blur-xl"><div className="flex h-[73px] items-center gap-3 px-4 sm:px-6 xl:px-8"><button type="button" onClick={onMenu} className="tct-menu-trigger rounded-xl p-2 text-slate-400 hover:bg-white/5 xl:hidden" aria-label="Abrir navegación"><Menu size={21} /></button><div className="flex shrink-0 items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-gradient-to-br from-sky-300 to-cyan-500 text-slate-950 shadow-lg shadow-cyan-950/30"><Navigation size={21} strokeWidth={2.5} /></span><div className="hidden sm:block"><p className="text-sm font-bold tracking-tight text-white">Aureon Logistics</p><p className="mt-0.5 text-[11px] text-slate-500">Operations cloud</p></div></div><div className="tct-header-context hidden min-w-0 flex-1 items-center gap-3 xl:flex"><span className="h-6 border-l border-white/10" /><div className="min-w-0"><p className="truncate text-xs font-medium text-slate-300">Operaciones <ChevronRight className="inline text-slate-600" size={13} /> Transportation Control Tower</p></div><HeaderSelect label="Andina Logística" /><HeaderSelect label="CD Lima Norte" /><HeaderSelect label="Hoy · 30 ago" icon={<CalendarDays size={14} />} /></div><button type="button" onClick={onCommand} className="ml-auto hidden min-w-[220px] items-center justify-between rounded-xl border border-white/8 bg-white/[.035] px-3 py-2 text-left text-xs text-slate-500 transition hover:border-white/15 hover:bg-white/6 lg:flex"><span className="flex items-center gap-2"><Search size={15} />Buscar rutas, vehículos o acciones</span><span className="rounded border border-white/10 px-1.5 py-0.5 text-[10px]">⌘ K</span></button><div className="relative"><button type="button" onClick={() => setMenuOpen(!menuOpen)} className={cx('hidden items-center gap-2 rounded-full border px-3 py-2 text-xs font-semibold md:flex', scenario === 'live' ? 'border-emerald-400/20 bg-emerald-400/8 text-emerald-300' : scenario === 'offline' ? 'border-amber-400/20 bg-amber-400/8 text-amber-200' : 'border-rose-400/20 bg-rose-400/8 text-rose-200')}><span className={cx('size-2 rounded-full', scenario === 'live' ? 'animate-pulse bg-emerald-400' : scenario === 'offline' ? 'bg-amber-400' : 'bg-rose-400')} />{scenarioCopy[0]}<ChevronDown size={13} /></button>{menuOpen && <div className="absolute right-0 top-11 z-50 w-64 rounded-2xl border border-white/10 bg-[#172235] p-2 shadow-2xl"><p className="px-3 py-2 text-xs text-slate-400">Estados del sistema</p>{[['live','En vivo'],['loading','Loading / skeleton'],['error','Error de carga'],['offline','Sin conexión']].map(([id,label]) => <button key={id} type="button" onClick={() => { onScenario(id); setMenuOpen(false) }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2.5 text-left text-sm text-slate-200 hover:bg-white/7"><span className={cx('size-2 rounded-full', id === 'live' ? 'bg-emerald-400' : id === 'offline' ? 'bg-amber-400' : id === 'error' ? 'bg-rose-400' : 'bg-sky-400')} />{label}</button>)}</div>}</div><NotificationButton open={notificationsOpen} setOpen={setNotificationsOpen} /><IconButton label="Centro de ayuda"><HelpCircle size={19} /></IconButton><button type="button" className="flex size-10 items-center justify-center rounded-full bg-violet-400/15 text-sm font-bold text-violet-200 ring-1 ring-violet-300/20" aria-label="Abrir menú de Andrea Ramos">AR</button></div></header>
}

function HeaderSelect({ label, icon }) { return <button type="button" className="inline-flex max-w-[154px] items-center gap-2 rounded-lg px-2.5 py-2 text-xs text-slate-400 transition hover:bg-white/6 hover:text-slate-200">{icon}{label}<ChevronDown size={13} className="shrink-0" /></button> }
function NotificationButton({ open, setOpen }) { return <div className="relative"><IconButton label="Notificaciones" onClick={() => setOpen(!open)} className="relative"><Bell size={19} /><span className="absolute right-1.5 top-1.5 size-2 rounded-full bg-rose-400 ring-2 ring-[#0d1626]" /></IconButton>{open && <div className="absolute right-0 top-12 z-50 w-[min(380px,calc(100vw-2rem))] rounded-2xl border border-white/10 bg-[#172235] p-3 shadow-2xl"><div className="flex items-center justify-between px-2 py-2"><div><p className="font-semibold text-white">Notificaciones</p><p className="mt-0.5 text-xs text-slate-400">4 requieren revisión</p></div><button type="button" onClick={() => toast.success('Notificaciones marcadas como leídas.')} className="text-xs font-semibold text-sky-300">Marcar leídas</button></div>{[['Crítica','TRK-284 mantiene una desviación activa','Hace 3 min','rose'],['SLA','7 rutas están próximas a incumplir SLA','Hace 8 min','amber'],['Documentos','3 guías requieren validación','Hace 14 min','sky']].map(([type,text,time,tone]) => <button key={text} type="button" className="mt-1 flex w-full gap-3 rounded-xl p-3 text-left hover:bg-white/6"><span className={cx('mt-1 size-2 shrink-0 rounded-full', tone === 'rose' ? 'bg-rose-400' : tone === 'amber' ? 'bg-amber-400' : 'bg-sky-400')} /><span><span className="block text-sm font-medium text-slate-100">{text}</span><span className="mt-1 block text-xs text-slate-500">{type} · {time}</span></span></button>)}</div>}</div> }

function Sidebar({ open, onClose }) { const [operationsOpen, setOperationsOpen] = useState(true); const nav = [{ icon:LayoutDashboard,label:'Overview' },{ icon:Map,label:'Control Tower',active:true },{ icon:Route,label:'Rutas',count:'186' },{ icon:Navigation,label:'Viajes' },{ icon:Truck,label:'Flota' },{ icon:UsersRound,label:'Conductores' },{ icon:PackageCheck,label:'Entregas' },{ icon:CircleAlert,label:'Incidencias',count:'12',danger:true }]; const planning = [{icon:CalendarDays,label:'Planificación'},{icon:Sparkles,label:'Optimización'},{icon:Fuel,label:'Costos'},{icon:FileText,label:'Documentos'},{icon:BarChartIcon,label:'Reportes'}]; return <aside className={cx('tct-sidebar z-50 border-r border-white/8 bg-[#0d1626] xl:sticky xl:top-[73px] xl:block xl:h-[calc(100vh-73px)] xl:overflow-y-auto', open && 'tct-sidebar-open fixed inset-y-0 left-0 w-[280px] shadow-2xl')}><div className="flex items-center justify-between px-4 pb-3 pt-5 xl:hidden"><p className="text-sm font-semibold text-white">Navegación</p><IconButton label="Cerrar navegación" onClick={onClose}><X size={18} /></IconButton></div><div className="p-3 xl:p-4"><NavGroup items={nav} /><div className="my-4 border-t border-white/7" /><button type="button" onClick={() => setOperationsOpen(!operationsOpen)} className="flex w-full items-center justify-between px-3 py-2 text-[11px] font-semibold uppercase tracking-[.13em] text-slate-500">Gestión <ChevronDown size={14} className={operationsOpen ? '' : '-rotate-90'} /></button>{operationsOpen && <NavGroup items={planning} />}<div className="my-4 border-t border-white/7" /><NavGroup items={[{icon:Settings2,label:'Configuración'}]} /><div className="mt-7 rounded-2xl border border-sky-400/12 bg-sky-400/[.055] p-4"><div className="flex items-center gap-2 text-sky-300"><Bot size={16} /><p className="text-xs font-semibold">Aureon Optimizer</p></div><p className="mt-2 text-xs leading-5 text-slate-400">Una propuesta puede ahorrar S/ 186 y 42 min hoy.</p><button type="button" className="mt-3 text-xs font-semibold text-sky-300 hover:text-sky-200">Ver propuesta</button></div></div></aside> }
function NavGroup({ items }) { return <div>{items.map(({icon:Icon,label,active,count,danger}) => <button type="button" key={label} className={cx('mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition', active ? 'bg-sky-400/12 text-sky-300' : 'text-slate-400 hover:bg-white/6 hover:text-slate-100')}><Icon size={17} /><span className="flex-1">{label}</span>{count && <span className={cx('rounded-full px-2 py-0.5 text-[11px] font-semibold', danger ? 'bg-rose-400/15 text-rose-300' : 'bg-white/8 text-slate-400')}>{count}</span>}</button>)}</div> }
function BarChartIcon(props) { return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}><path d="M4 20V10M10 20V4M16 20v-7M22 20H2" /></svg> }

function PageHeading({ onCreate, onOptimize }) { return <section className="flex flex-wrap items-end justify-between gap-5"><div><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[.15em] text-sky-300"><Map size={15} />Operación nacional</div><h1 className="mt-3 text-3xl font-semibold tracking-[-.045em] text-white sm:text-4xl">Transportation Control Tower</h1><p className="mt-3 max-w-2xl text-[15px] leading-6 text-slate-400">Supervisa rutas, excepciones, capacidad y compromisos de servicio en una única vista operacional.</p></div><div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={onOptimize}><Sparkles size={16} />Optimizar rutas</Button><Button variant="primary" onClick={onCreate}><Plus size={17} />Crear viaje</Button></div></section> }

function FilterBar({ open, setOpen, filters, updateFilter, query, setQuery, chips, removeChip, clearFilters }) { return <section className="mt-7 rounded-2xl border border-white/8 bg-[#111c2e] p-3 sm:p-4"><div className="flex flex-wrap items-center gap-3"><label className="flex min-h-11 min-w-[230px] flex-1 items-center gap-2 rounded-xl border border-white/8 bg-[#09111f] px-3.5 focus-within:border-sky-400/45"><Search size={17} className="text-slate-500" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar ruta, vehículo, conductor o transportista" className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-slate-500" /></label><Button variant={open ? 'primary' : 'secondary'} onClick={() => setOpen(!open)}><ListFilter size={16} />Filtros{chips.length > 0 && <span className="rounded-md bg-slate-950/25 px-1.5 py-0.5 text-[11px]">{chips.length}</span>}</Button>{(chips.length > 0 || query) && <button type="button" onClick={clearFilters} className="px-2 text-xs font-semibold text-slate-400 hover:text-white">Limpiar</button>}</div>{chips.length > 0 && <div className="flex flex-wrap gap-2 pt-3">{chips.map(({key,value}) => <button key={key} type="button" onClick={() => removeChip(key)} className="inline-flex items-center gap-1.5 rounded-full border border-sky-400/15 bg-sky-400/8 px-2.5 py-1.5 text-xs font-medium text-sky-200">{filterLabel(key)}: {value}<X size={13} /></button>)}</div>}{open && <div className="mt-4 grid gap-4 border-t border-white/7 pt-4 sm:grid-cols-2 xl:grid-cols-4"><FilterSelect label="Estado" value={filters.status} onChange={v => updateFilter('status',v)} options={STATUS} /><FilterSelect label="Transportista" value={filters.carrier} onChange={v => updateFilter('carrier',v)} options={['Todos','Transportes Andinos','Logística Pacífico','Carga Express Perú','Transporte Continental']} /><FilterSelect label="Tipo de vehículo" value={filters.vehicle} onChange={v => updateFilter('vehicle',v)} options={['Todos','Tracto','Furgón','Refrigerado']} /><FilterSelect label="Centro logístico" value={filters.hub} onChange={v => updateFilter('hub',v)} options={['Lima · Centro','Callao','Arequipa','Chiclayo']} /><FilterSelect label="Cliente" value={filters.client} onChange={v => updateFilter('client',v)} options={['Todos','Grupo Andino','Distribuciones Norte','Comercial Pacífico']} /><FilterSelect label="Zona geográfica" value={filters.zone} onChange={v => updateFilter('zone',v)} options={['Nacional','Costa norte','Centro','Sur']} /><FilterSelect label="Conductor" value={filters.driver} onChange={v => updateFilter('driver',v)} options={['Todos', ...TRIPS.map(item => item.driver)]} /><FilterSelect label="Rango de fechas" value={filters.date} onChange={v => updateFilter('date',v)} options={['Hoy','Últimas 24 h','Esta semana','Personalizado']} /></div>}</section> }
function FilterSelect({ label,value,onChange,options }) { return <label className="text-xs font-medium text-slate-400"><span className="mb-2 block">{label}</span><span className="relative block"><select value={value} onChange={event => onChange(event.target.value)} className="h-11 w-full appearance-none rounded-xl border border-white/8 bg-[#09111f] px-3 text-sm text-slate-200 outline-none focus:border-sky-400/45">{options.map(option => <option key={option}>{option}</option>)}</select><ChevronDown size={15} className="pointer-events-none absolute right-3 top-3 text-slate-500" /></span></label> }
function filterLabel(key) { return {status:'Estado',carrier:'Transportista',vehicle:'Vehículo',hub:'Centro',client:'Cliente',zone:'Zona',driver:'Conductor',date:'Fecha'}[key] }

function CriticalStrip({ onOpen, onIncidence }) { return <section className="mt-5 flex flex-wrap items-center gap-x-6 gap-y-3 rounded-2xl border border-rose-400/15 bg-rose-400/[.055] px-4 py-3.5"><span className="flex items-center gap-2 text-sm font-semibold text-rose-200"><span className="relative flex size-5 items-center justify-center"><span className="absolute size-5 animate-ping rounded-full bg-rose-400/25" /><CircleAlert size={18} className="relative text-rose-300" /></span>2 situaciones requieren intervención</span><span className="text-sm text-slate-400">TRK-284 fuera de ruta · 4.8 km de desviación</span><button type="button" onClick={onOpen} className="text-sm font-semibold text-rose-200 hover:text-white">Investigar ahora <ChevronRight className="inline" size={15} /></button><button type="button" onClick={onIncidence} className="ml-auto text-xs font-semibold text-slate-400 hover:text-white">Reportar incidencia</button></section> }

function KpiGrid() { return <section className="tct-kpis mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">{KPI_DATA.map(({label,value,detail,tone,icon:Icon,progress,spark}) => <article key={label} className="group min-w-0 rounded-2xl border border-white/8 bg-[#111c2e] p-4 transition hover:-translate-y-0.5 hover:border-white/15 hover:bg-[#15233a]"><div className="flex items-start justify-between gap-3"><div><p className="text-[11px] font-semibold uppercase tracking-[.1em] text-slate-500">{label}</p><p className="mt-2 whitespace-nowrap text-2xl font-semibold tracking-[-.04em] text-white">{value}</p></div><span className={cx('grid size-9 place-items-center rounded-xl border', toneClass[tone])}><Icon size={17} /></span></div>{progress ? <div className="mt-3"><Progress value={progress} tone="emerald" label={false} /></div> : spark ? <Sparkline /> : <p className={cx('mt-3 flex items-center gap-1 text-xs font-medium', tone === 'rose' ? 'text-rose-300' : tone === 'amber' ? 'text-amber-300' : 'text-slate-400')}>{tone === 'rose' ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{detail}</p>}</article>)}</section> }
function Sparkline() { return <svg className="mt-3 h-6 w-full" viewBox="0 0 120 24" preserveAspectRatio="none" aria-label="Tendencia favorable de utilización"><path d="M0 20 L15 18 L28 20 L42 13 L57 15 L70 8 L86 11 L103 5 L120 7" fill="none" stroke="#22d3ee" strokeWidth="2" vectorEffect="non-scaling-stroke" /><path d="M0 24 L0 20 L15 18 L28 20 L42 13 L57 15 L70 8 L86 11 L103 5 L120 7 L120 24" fill="url(#sparkfill)" opacity=".25" /><defs><linearGradient id="sparkfill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#22d3ee" /><stop offset="1" stopColor="#22d3ee" stopOpacity="0" /></linearGradient></defs></svg> }

function Panel({ eyebrow, title, action, children, className = '' }) { return <section className={cx('overflow-hidden rounded-2xl border border-white/8 bg-[#111c2e]', className)}><header className="flex flex-wrap items-start justify-between gap-4 border-b border-white/7 px-5 py-4 sm:px-6"><div>{eyebrow && <p className="text-[11px] font-semibold uppercase tracking-[.12em] text-sky-300">{eyebrow}</p>}<h2 className="mt-1 text-lg font-semibold tracking-[-.025em] text-white">{title}</h2></div>{action}</header>{children}</section> }

function OperationalMap({ onOpen, onIncident }) { const [hovered,setHovered] = useState(null); return <Panel eyebrow="TRACKING EN TIEMPO REAL" title="Mapa operacional" action={<div className="flex items-center gap-2"><Chip tone="emerald"><Wifi size={12} />143 conectados</Chip><IconButton label="Opciones del mapa"><MoreHorizontal size={18} /></IconButton></div>}><div className="relative h-[430px] overflow-hidden bg-[#0a1422] sm:h-[510px]"><MapGrid /><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full"><path d="M10 79 C28 58 31 45 56 47 S76 31 93 13" fill="none" stroke="#38bdf8" strokeDasharray="1.4 1.8" strokeWidth=".7" opacity=".7" /><path d="M16 17 C33 26 41 40 52 61 S69 70 88 83" fill="none" stroke="#fbbf24" strokeDasharray="1.4 1.8" strokeWidth=".7" opacity=".65" /><path d="M17 17 L41 42 L56 47 L62 70" fill="none" stroke="#64748b" strokeWidth=".5" opacity=".55" /><circle cx="12" cy="80" r="1.8" fill="#22d3ee" /><circle cx="93" cy="13" r="1.8" fill="#22d3ee" /><circle cx="16" cy="17" r="1.8" fill="#22d3ee" /><circle cx="88" cy="83" r="1.8" fill="#22d3ee" /></svg>{TRIPS.slice(0,5).map(item => <button key={item.id} type="button" onMouseEnter={() => setHovered(item)} onMouseLeave={() => setHovered(null)} onFocus={() => setHovered(item)} onBlur={() => setHovered(null)} onClick={() => onOpen(item)} className="absolute z-10 -translate-x-1/2 -translate-y-1/2" style={{left:item.coords[0],top:item.coords[1]}} aria-label={`Abrir ${item.id}: ${item.status}`}><span className={cx('grid size-10 place-items-center rounded-full border-4 border-[#0a1422] shadow-lg transition hover:scale-110', item.risk === 'Crítico' ? 'bg-rose-400 text-white' : item.risk === 'Riesgo' ? 'bg-amber-300 text-slate-950' : item.status === 'Detenida' ? 'bg-slate-400 text-slate-900' : 'bg-emerald-400 text-slate-950')}><Truck size={17} /></span></button>)}{hovered && <MapPopup trip={hovered} onOpen={() => onOpen(hovered)} onIncident={onIncident} />}<div className="absolute bottom-4 left-4 flex flex-wrap gap-x-4 gap-y-2 rounded-xl border border-white/10 bg-[#0d1626]/90 px-3 py-2 text-xs text-slate-300 backdrop-blur"><Legend tone="emerald" label="Normal" /><Legend tone="amber" label="Riesgo" /><Legend tone="rose" label="Crítico" /><Legend tone="slate" label="Detenido" /></div><div className="absolute right-4 top-4 flex flex-col gap-2"><IconButton label="Acercar" className="border border-white/10 bg-[#0d1626]/90 text-white">+</IconButton><IconButton label="Alejar" className="border border-white/10 bg-[#0d1626]/90 text-white">−</IconButton></div></div></Panel> }
function MapGrid() { return <div className="absolute inset-0 opacity-60" style={{backgroundImage:'linear-gradient(rgba(71, 112, 150, .10) 1px, transparent 1px), linear-gradient(90deg, rgba(71, 112, 150, .10) 1px, transparent 1px), radial-gradient(circle at 58% 50%, rgba(56,189,248,.12), transparent 34%)',backgroundSize:'42px 42px,42px 42px,100% 100%'}}><div className="absolute inset-x-[7%] top-[55%] h-px rotate-[-22deg] bg-sky-400/15" /><div className="absolute left-[38%] top-[-5%] h-[110%] w-px rotate-[27deg] bg-sky-400/10" /></div> }
function MapPopup({ trip, onOpen, onIncident }) { return <div className="absolute bottom-5 left-5 z-20 w-[min(360px,calc(100%-2.5rem))] rounded-2xl border border-white/12 bg-[#172235]/95 p-4 shadow-2xl backdrop-blur"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-sky-300">{trip.vehicle} · {trip.id}</p><p className="mt-1 text-sm font-semibold text-white">{trip.driver}</p><p className="mt-1 text-xs text-slate-400">{trip.origin} → {trip.destination}</p></div><StatusBadge status={trip.status} /></div><div className="mt-4 grid grid-cols-3 gap-3 text-xs"><span><span className="block text-slate-500">Velocidad</span><strong className="mt-1 block text-slate-100">67 km/h</strong></span><span><span className="block text-slate-500">ETA</span><strong className="mt-1 block text-slate-100">{trip.eta}</strong></span><span><span className="block text-slate-500">Próxima entrega</span><strong className="mt-1 block truncate text-slate-100">Grupo Andino</strong></span></div><div className="mt-4"><Progress value={trip.progress} tone={trip.risk === 'Crítico' ? 'rose' : trip.risk === 'Riesgo' ? 'amber' : 'emerald'} /></div><div className="mt-4 flex flex-wrap gap-2"><Button className="flex-1" variant="primary" onClick={onOpen}>Ver viaje</Button><Button variant="secondary" onClick={() => toast.success('Canal de contacto preparado.')}>Contactar</Button><IconButton label="Reportar incidencia" onClick={onIncident} className="border border-white/10"><CircleAlert size={17} /></IconButton></div></div> }
function Legend({ tone,label }) { return <span className="inline-flex items-center gap-1.5"><span className={cx('size-2 rounded-full', tone === 'emerald' ? 'bg-emerald-400' : tone === 'amber' ? 'bg-amber-400' : tone === 'rose' ? 'bg-rose-400' : 'bg-slate-400')} />{label}</span> }

function AlertsPanel({ onOpen, onIncident }) { const alerts = [{trip:TRIPS[1],label:'Fuera de ruta',detail:'Desviación de 4.8 km',tone:'rose',time:'Hace 3 min'},{trip:TRIPS[0],label:'Riesgo de retraso',detail:'27 min estimados',tone:'amber',time:'Hace 5 min'},{trip:TRIPS[3],label:'Unidad detenida',detail:'Revisión preventiva',tone:'amber',time:'Hace 7 min'},{trip:TRIPS[5],label:'Entrega completada',detail:'POD validado',tone:'sky',time:'Hace 12 min'}]; return <Panel eyebrow="EXCEPCIONES" title="Alertas operacionales" action={<button type="button" className="text-sm font-semibold text-sky-300 hover:text-sky-200">Ver 12 alertas</button>}><div className="divide-y divide-white/7">{alerts.map(({trip,label,detail,tone,time}) => <article key={trip.id} className="group flex gap-3 px-5 py-4 sm:px-6"><span className={cx('mt-1 grid size-9 shrink-0 place-items-center rounded-xl', tone === 'rose' ? 'bg-rose-400/12 text-rose-300' : tone === 'amber' ? 'bg-amber-400/12 text-amber-300' : 'bg-sky-400/12 text-sky-300')}><CircleAlert size={17} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><button type="button" onClick={() => onOpen(trip)} className="text-left text-sm font-semibold text-slate-100 hover:text-sky-300">{trip.id} · {label}</button><span className="shrink-0 text-[11px] text-slate-500">{time}</span></div><p className="mt-1 text-sm text-slate-400">{detail} · {trip.location}</p><div className="mt-2 flex gap-3"><button type="button" onClick={() => onOpen(trip)} className="text-xs font-semibold text-sky-300">Abrir detalle</button><button type="button" onClick={() => toast.success('Alerta marcada como revisada.')} className="text-xs font-semibold text-slate-400 hover:text-white">Revisada</button>{tone !== 'sky' && <button type="button" onClick={onIncident} className="text-xs font-semibold text-amber-300">Crear incidencia</button>}</div></div></article>)}</div><div className="border-t border-white/7 px-5 py-3 text-xs text-slate-500 sm:px-6">Ordenadas por impacto operacional y antigüedad.</div></Panel> }

function AnalyticsSection() { return <section className="tct-analytics mt-6 grid gap-5 xl:grid-cols-2 2xl:grid-cols-4"><ChartPanel eyebrow="VOLUMEN" title="Entregas por hora" action="Hoy"><ResponsiveContainer width="100%" height={180}><LineChart data={chartHourly}><XAxis dataKey="h" axisLine={false} tickLine={false} tick={{fill:'#64748b',fontSize:11}} /><YAxis hide /><Tooltip content={<ChartTooltip />} /><Line type="monotone" dataKey="promedio" stroke="#64748b" strokeDasharray="4 4" strokeWidth={2} dot={false} /><Line type="monotone" dataKey="hoy" stroke="#38bdf8" strokeWidth={2.5} dot={false} /></LineChart></ResponsiveContainer><div className="flex gap-4 text-xs text-slate-400"><span><i className="mr-1 inline-block size-2 rounded-full bg-sky-400" />Hoy</span><span><i className="mr-1 inline-block size-2 rounded-full bg-slate-500" />Promedio 7 días</span></div></ChartPanel><ChartPanel eyebrow="SERVICIO" title="Cumplimiento SLA" action="Hoy"><div className="relative h-[180px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={slaChart} dataKey="value" innerRadius={52} outerRadius={72} paddingAngle={3} stroke="none">{slaChart.map(item => <Cell key={item.name} fill={item.color} />)}</Pie><Tooltip content={<ChartTooltip />} /></PieChart></ResponsiveContainer><div className="pointer-events-none absolute inset-0 grid place-items-center text-center"><strong className="text-2xl tracking-[-.04em] text-white">94.8%</strong><span className="-mt-8 text-[10px] uppercase tracking-wide text-slate-500">On time</span></div></div><div className="flex justify-center gap-3 text-[11px] text-slate-400">{slaChart.map(item => <span key={item.name}><i className="mr-1 inline-block size-2 rounded-full" style={{background:item.color}} />{item.name}</span>)}</div></ChartPanel><ChartPanel eyebrow="CAPACIDAD" title="Estado de rutas" action="Hoy"><ResponsiveContainer width="100%" height={180}><BarChart data={chartRoute} layout="vertical" margin={{left:0,right:8}}><XAxis type="number" hide /><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#94a3b8',fontSize:11}} width={82} /><Tooltip content={<ChartTooltip />} /><Bar dataKey="value" radius={[0,6,6,0]}>{chartRoute.map(item => <Cell key={item.name} fill={item.fill} />)}</Bar></BarChart></ResponsiveContainer><p className="text-xs text-slate-400">181 rutas programadas durante la jornada.</p></ChartPanel><ChartPanel eyebrow="EFICIENCIA" title="Costo por transportista" action="PEN miles"><ResponsiveContainer width="100%" height={180}><BarChart data={chartCost} barGap={3}><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#64748b',fontSize:10}} /><YAxis hide /><Tooltip content={<ChartTooltip />} /><Bar dataKey="presupuesto" fill="#475569" radius={[5,5,0,0]} /><Bar dataKey="real" fill="#fbbf24" radius={[5,5,0,0]} /></BarChart></ResponsiveContainer><div className="flex gap-4 text-xs text-slate-400"><span><i className="mr-1 inline-block size-2 rounded-sm bg-amber-300" />Real</span><span><i className="mr-1 inline-block size-2 rounded-sm bg-slate-600" />Presupuesto</span></div></ChartPanel></section> }
function ChartPanel({eyebrow,title,action,children}) { return <section className="rounded-2xl border border-white/8 bg-[#111c2e] p-5"><header className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-semibold uppercase tracking-[.13em] text-slate-500">{eyebrow}</p><h3 className="mt-1 text-sm font-semibold text-slate-100">{title}</h3></div><span className="text-xs text-slate-500">{action}</span></header><div className="mt-3">{children}</div></section> }
function ChartTooltip({ active,payload,label }) { if (!active || !payload?.length) return null; return <div className="rounded-xl border border-white/10 bg-[#172235] px-3 py-2 text-xs shadow-xl"><p className="mb-1 text-slate-400">{label}</p>{payload.map(item => <p key={item.name} style={{color:item.color}}>{item.name}: <b>{item.value}{item.name === 'hoy' || item.name === 'promedio' ? ' entregas' : '%'}</b></p>)}</div> }

function RoutesTable({ rows,total,page,totalPages,setPage,sort,onSort,selected,toggleSelected,toggleAll,expanded,setExpanded,openTrip,openModal,density,setDensity,columnsOpen,setColumnsOpen,visibleColumns,setVisibleColumns,clearFilters }) { const allSelected = rows.length > 0 && rows.every(item => selected.includes(item.id)); const start = total ? (page - 1) * 5 + 1 : 0; const end = Math.min(page * 5,total); const compact = density === 'compact'; return <section className="mt-6 overflow-hidden rounded-2xl border border-white/8 bg-[#111c2e]"><header className="flex flex-wrap items-center justify-between gap-4 border-b border-white/7 px-5 py-5 sm:px-6"><div><p className="text-[11px] font-semibold uppercase tracking-[.12em] text-sky-300">EJECUCIÓN</p><h2 className="mt-1 text-xl font-semibold tracking-[-.03em] text-white">Rutas activas</h2><p className="mt-1 text-sm text-slate-500">Sigue cada compromiso sin abrir una hoja de cálculo.</p></div><div className="flex flex-wrap items-center gap-2">{selected.length > 0 && <div className="flex items-center gap-2 rounded-xl border border-sky-400/15 bg-sky-400/8 p-1.5"><span className="px-2 text-xs font-semibold text-sky-200">{selected.length} seleccionadas</span><Button variant="secondary" className="min-h-8 px-3 py-1.5 text-xs" onClick={() => toast.success('Responsable masivo preparado.')}>Asignar</Button><IconButton label="Exportar seleccionadas" onClick={() => toast.success('Exportación generada.')} className="size-8"><Download size={15} /></IconButton></div>}<div className="relative"><Button variant="secondary" className="min-h-10 px-3" onClick={() => setColumnsOpen(!columnsOpen)}><SlidersHorizontal size={16} />Columnas</Button>{columnsOpen && <div className="absolute right-0 top-12 z-30 w-56 rounded-2xl border border-white/10 bg-[#172235] p-2 shadow-2xl"><p className="px-3 py-2 text-xs text-slate-400">Columnas visibles</p>{Object.entries({carrier:'Transportista',cost:'Costo',sla:'SLA',incidents:'Incidencias'}).map(([key,label]) => <label key={key} className="flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-slate-200 hover:bg-white/6"><input type="checkbox" checked={visibleColumns[key]} onChange={event => setVisibleColumns(current => ({...current,[key]:event.target.checked}))} className="size-4 accent-sky-400" />{label}</label>)}</div>}</div><button type="button" onClick={() => setDensity(compact ? 'comfortable' : 'compact')} className="rounded-xl border border-white/10 px-3 py-2.5 text-xs font-semibold text-slate-400 hover:bg-white/6">{compact ? 'Vista cómoda' : 'Vista compacta'}</button></div></header><div className="hidden overflow-x-auto lg:block"><table className="w-full min-w-[1250px] text-left"><thead className="sticky top-0 z-10 bg-[#152136] text-[10px] font-semibold uppercase tracking-[.11em] text-slate-500"><tr><th className="sticky left-0 z-10 bg-[#152136] px-5 py-4"><input type="checkbox" checked={allSelected} onChange={toggleAll} aria-label="Seleccionar rutas visibles" className="size-4 accent-sky-400" /></th><SortHead label="Ruta" field="id" sort={sort} onSort={onSort} /><SortHead label="Origen / destino" field="origin" sort={sort} onSort={onSort} /><SortHead label="Vehículo" field="vehicle" sort={sort} onSort={onSort} />{visibleColumns.carrier && <SortHead label="Transportista" field="carrier" sort={sort} onSort={onSort} />}<SortHead label="Estado" field="status" sort={sort} onSort={onSort} /><th className="px-4 py-4">Progreso</th><SortHead label="ETA" field="eta" sort={sort} onSort={onSort} />{visibleColumns.sla && <SortHead label="SLA" field="sla" sort={sort} onSort={onSort} />}{visibleColumns.incidents && <th className="px-4 py-4">Incidencias</th>}{visibleColumns.cost && <SortHead label="Costo" field="cost" sort={sort} onSort={onSort} />}<th className="sticky right-0 z-10 bg-[#152136] px-5 py-4 text-right">Acciones</th></tr></thead><tbody>{rows.map(item => <RouteRow key={item.id} item={item} selected={selected.includes(item.id)} onSelect={() => toggleSelected(item.id)} expanded={expanded === item.id} setExpanded={() => setExpanded(expanded === item.id ? null : item.id)} openTrip={() => openTrip(item)} openModal={openModal} visibleColumns={visibleColumns} compact={compact} />)}</tbody></table>{!rows.length && <EmptyRoutes onClear={clearFilters} />}</div><div className="space-y-3 p-4 lg:hidden">{rows.map(item => <MobileRouteCard key={item.id} item={item} openTrip={() => openTrip(item)} />)}{!rows.length && <EmptyRoutes onClear={clearFilters} />}</div>{total > 0 && <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-white/7 px-5 py-4 text-sm text-slate-400 sm:px-6"><span>Mostrando {start}–{end} de {total} rutas</span><Pagination page={page} total={totalPages} setPage={setPage} /></footer>}</section> }
function SortHead({label,field,sort,onSort}) { return <th className="px-4 py-4"><button type="button" onClick={() => onSort(field)} className="inline-flex items-center gap-1 hover:text-slate-200">{label}{sort.key === field ? sort.direction === 'asc' ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} /> : <ChevronDown size={12} className="opacity-40" />}</button></th> }
function RouteRow({item,selected,onSelect,expanded,setExpanded,openTrip,openModal,visibleColumns,compact}) { return <><tr className={cx('border-t border-white/6 text-sm transition hover:bg-white/[.035]', selected && 'bg-sky-400/[.055]')}><td className={cx('sticky left-0 z-[1] bg-[#111c2e] px-5', compact ? 'py-3' : 'py-4')}><input type="checkbox" checked={selected} onChange={onSelect} aria-label={`Seleccionar ${item.id}`} className="size-4 accent-sky-400" /></td><td className={cx('px-4', compact ? 'py-3' : 'py-4')}><button type="button" onClick={openTrip} className="text-left"><span className="block font-semibold text-slate-100 hover:text-sky-300">{item.id}</span><span className="mt-1 block text-xs text-slate-500">{item.lastUpdate}</span></button></td><td className="px-4 py-4"><p className="font-medium text-slate-200">{item.origin} → {item.destination}</p><p className="mt-1 text-xs text-slate-500">{item.deliveries} entregas</p></td><td className="px-4 py-4"><p className="font-medium text-slate-200">{item.vehicle}</p><p className="mt-1 text-xs text-slate-500">{item.driver}</p></td>{visibleColumns.carrier && <td className="px-4 py-4 text-slate-400">{item.carrier}</td>}<td className="px-4 py-4"><StatusBadge status={item.status} /></td><td className="px-4 py-4"><Progress value={item.progress} tone={item.risk === 'Crítico' ? 'rose' : item.risk === 'Riesgo' ? 'amber' : 'sky'} /></td><td className="px-4 py-4"><span className="font-medium text-slate-200">{item.eta}</span><p className={cx('mt-1 text-xs', item.delay !== '—' ? 'text-amber-300' : 'text-slate-500')}>{item.delay !== '—' ? `+${item.delay}` : 'En tiempo'}</p></td>{visibleColumns.sla && <td className="px-4 py-4"><Chip tone={item.sla < 85 ? 'rose' : item.sla < 95 ? 'amber' : 'emerald'}>{item.sla}%</Chip></td>}{visibleColumns.incidents && <td className="px-4 py-4"><span className={cx('inline-flex size-7 items-center justify-center rounded-lg text-xs font-bold', item.incidents ? 'bg-rose-400/12 text-rose-300' : 'bg-white/5 text-slate-500')}>{item.incidents}</span></td>}{visibleColumns.cost && <td className="px-4 py-4 font-medium text-slate-200">{item.cost}</td>}<td className="sticky right-0 z-[1] bg-[#111c2e] px-5 py-4 text-right"><div className="flex justify-end gap-1"><IconButton label="Expandir viaje" onClick={setExpanded} className="size-8"><ChevronDown size={16} className={expanded ? 'rotate-180' : ''} /></IconButton><RouteMenu onOpen={openTrip} onIncident={() => openModal('incidence')} /></div></td></tr>{expanded && <tr className="border-t border-white/6 bg-[#0d1626]"><td colSpan={14} className="px-5 py-5"><ExpandedRoute item={item} openTrip={openTrip} /></td></tr>}</> }
function RouteMenu({onOpen,onIncident}) { const [open,setOpen] = useState(false); return <div className="relative"><IconButton label="Más acciones" onClick={() => setOpen(!open)} className="size-8"><MoreHorizontal size={17} /></IconButton>{open && <div className="absolute right-0 top-9 z-30 w-48 rounded-xl border border-white/10 bg-[#172235] p-1.5 text-left shadow-2xl"><button type="button" onClick={onOpen} className="w-full rounded-lg px-3 py-2.5 text-sm text-slate-200 hover:bg-white/6">Abrir viaje</button><button type="button" onClick={onIncident} className="w-full rounded-lg px-3 py-2.5 text-sm text-amber-200 hover:bg-white/6">Reportar incidencia</button><button type="button" onClick={() => toast.success('Ruta escalada al equipo de operaciones.')} className="w-full rounded-lg px-3 py-2.5 text-sm text-rose-200 hover:bg-white/6">Escalar ruta</button></div>}</div> }
function ExpandedRoute({item,openTrip}) { return <div className="grid gap-5 xl:grid-cols-[1.4fr_.9fr_.8fr]"><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-slate-500">Timeline del viaje</p><ol className="mt-4 grid gap-3 sm:grid-cols-2">{[['08:15','Vehículo asignado'],['08:32','Carga completada'],['08:45','Salida del centro logístico'],['10:20','Entrega cliente #1'],['11:42',item.incidents ? 'Incidencia reportada' : 'Tracking validado'],['12:05','Ruta reanudada']].map(([time,event],index) => <li key={time} className="flex gap-3"><span className={cx('mt-1.5 size-2 shrink-0 rounded-full', index === 4 && item.incidents ? 'bg-rose-400 ring-4 ring-rose-400/12' : 'bg-sky-400')} /><span><strong className="block text-xs text-slate-400">{time}</strong><span className="mt-1 block text-sm text-slate-200">{event}</span></span></li>)}</ol></div><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-slate-500">Ubicación y documentos</p><p className="mt-4 flex items-center gap-2 text-sm text-slate-200"><MapPin size={16} className="text-sky-300" />{item.location}</p><div className="mt-4 flex gap-2"><Chip tone="slate"><FileText size={12} />Guía firmada</Chip><Chip tone="emerald"><Check size={12} />POD validado</Chip></div></div><div className="rounded-xl border border-sky-400/15 bg-sky-400/[.06] p-4"><p className="text-xs font-semibold text-sky-200">Seguimiento</p><p className="mt-2 text-sm leading-6 text-slate-300">{item.notes}</p><button type="button" onClick={openTrip} className="mt-4 text-sm font-semibold text-sky-300">Abrir detalle completo <ChevronRight className="inline" size={15} /></button></div></div> }
function MobileRouteCard({item,openTrip}) { return <article className="rounded-xl border border-white/8 bg-[#0d1626] p-4"><div className="flex items-start justify-between gap-3"><button type="button" onClick={openTrip} className="text-left"><p className="font-semibold text-slate-100">{item.id}</p><p className="mt-1 text-sm text-slate-400">{item.origin} → {item.destination}</p></button><StatusBadge status={item.status} /></div><div className="mt-4 grid grid-cols-2 gap-3 text-sm"><span className="text-slate-500">Vehículo <strong className="mt-1 block text-slate-200">{item.vehicle}</strong></span><span className="text-slate-500">ETA <strong className="mt-1 block text-slate-200">{item.eta}</strong></span></div><div className="mt-4"><Progress value={item.progress} tone={item.risk === 'Crítico' ? 'rose' : item.risk === 'Riesgo' ? 'amber' : 'sky'} /></div></article> }
function EmptyRoutes({onClear}) { return <div className="px-6 py-16 text-center"><span className="mx-auto grid size-12 place-items-center rounded-2xl bg-white/5 text-slate-500"><Filter size={20} /></span><p className="mt-4 text-lg font-semibold text-slate-100">No hay rutas para estos filtros</p><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-400">Prueba eliminando un filtro o crea una nueva ruta para continuar.</p><Button variant="secondary" className="mt-5" onClick={onClear}>Limpiar filtros</Button></div> }
function Pagination({page,total,setPage}) { return <div className="flex items-center gap-1"><IconButton label="Página anterior" onClick={() => setPage(Math.max(1,page-1))} className="size-8" disabled={page===1}><ChevronLeft size={16} /></IconButton>{Array.from({length:total},(_,index) => index+1).map(value => <button key={value} type="button" onClick={() => setPage(value)} className={cx('size-8 rounded-lg text-xs font-semibold', value===page ? 'bg-sky-400 text-slate-950' : 'text-slate-400 hover:bg-white/7')}>{value}</button>)}<IconButton label="Página siguiente" onClick={() => setPage(Math.min(total,page+1))} className="size-8" disabled={page===total}><ChevronRight size={16} /></IconButton></div> }

function TripDrawer({trip,tab,setTab,onClose,onIncidence,onReplan,onLightbox}) { const tabs = ['Resumen','Entregas','Tracking','Documentos','Incidencias','Costos']; return <><div className="fixed inset-0 z-50 bg-slate-950/60 backdrop-blur-[1px]" onMouseDown={onClose} role="presentation" /><aside role="dialog" aria-modal="true" aria-labelledby="trip-title" className="fixed bottom-3 right-3 top-3 z-[60] flex w-[min(520px,calc(100vw-1.5rem))] flex-col overflow-hidden rounded-3xl border border-white/10 bg-[#111c2e] shadow-2xl"><header className="border-b border-white/7 px-6 py-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.13em] text-sky-300">Viaje en curso</p><h2 id="trip-title" className="mt-2 text-2xl font-semibold tracking-[-.035em] text-white">{trip.id}</h2><p className="mt-1 text-sm text-slate-400">{trip.origin} → {trip.destination}</p></div><IconButton label="Cerrar detalle" onClick={onClose}><X size={20} /></IconButton></div><div className="mt-4 flex flex-wrap gap-2"><StatusBadge status={trip.status} /><Chip tone={riskTone[trip.risk]}>{trip.risk}</Chip><span className="self-center text-xs text-slate-500">Actualizado {trip.lastUpdate}</span></div></header><nav className="overflow-x-auto border-b border-white/7 px-6" aria-label="Detalle del viaje"><div className="flex min-w-max gap-5">{tabs.map(item => <button key={item} type="button" onClick={() => setTab(item)} className={cx('border-b-2 py-3.5 text-sm font-medium transition', tab===item ? 'border-sky-400 text-sky-300' : 'border-transparent text-slate-500 hover:text-slate-200')}>{item}</button>)}</div></nav><div className="min-h-0 flex-1 overflow-y-auto px-6 py-6">{tab==='Resumen' && <DrawerSummary trip={trip} onIncidence={onIncidence} onReplan={onReplan} onLightbox={onLightbox} />}{tab==='Entregas' && <DrawerDeliveries trip={trip} />}{tab==='Tracking' && <DrawerTracking trip={trip} />}{tab==='Documentos' && <DrawerDocuments onLightbox={onLightbox} />}{tab==='Incidencias' && <DrawerIncidents trip={trip} onIncidence={onIncidence} />}{tab==='Costos' && <DrawerCosts trip={trip} />}</div><footer className="grid grid-cols-2 gap-3 border-t border-white/7 bg-[#0d1626] p-4"><Button variant="secondary" onClick={() => toast.success('Canal seguro con el conductor iniciado.')}><Phone size={16} />Contactar</Button><Button variant="primary" onClick={onIncidence}><CircleAlert size={16} />Incidencia</Button></footer></aside></> }
function DrawerSummary({trip,onIncidence,onReplan,onLightbox}) { return <div className="space-y-6"><section className="grid grid-cols-2 gap-3"><SummaryMetric label="ETA actualizado" value={trip.eta} hint={trip.delay === '—' ? 'Dentro de ventana' : `+${trip.delay} estimados`} tone={trip.delay === '—' ? 'emerald' : 'amber'} /><SummaryMetric label="Progreso" value={`${trip.progress}%`} hint={`${trip.deliveries} entregas`} tone="sky" /></section><section className="rounded-2xl border border-white/8 bg-[#0d1626] p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-slate-500">Conductor</p><p className="mt-2 text-base font-semibold text-white">{trip.driver}</p><p className="mt-1 text-sm text-slate-400">4.8 ★ · 1,284 viajes</p></div><div className="grid size-12 place-items-center rounded-full bg-violet-400/15 text-sm font-bold text-violet-200">CM</div></div><div className="mt-4 flex gap-2"><Button variant="secondary" className="flex-1" onClick={() => toast.success('Llamada al conductor iniciada.')}><Phone size={15} />Llamar</Button><Button variant="secondary" className="flex-1" onClick={() => toast.success('Mensaje preparado.')}><Send size={15} />Mensaje</Button></div></section><section className="overflow-hidden rounded-2xl border border-white/8 bg-[#0d1626]"><div className="relative h-36 overflow-hidden"><EvidenceTile index={0} className="absolute inset-0" /><div className="absolute inset-0 bg-gradient-to-t from-[#0d1626] via-transparent to-transparent" /><Chip tone="sky" className="absolute right-3 top-3">TRK-248</Chip></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-white">Mercedes Actros 2651</p><p className="mt-1 text-sm text-slate-400">Placa ABC-284 · Tracto · 30 Tn</p></div><Truck size={19} className="text-sky-300" /></div><div className="mt-4"><div className="flex justify-between text-xs text-slate-400"><span>Carga actual</span><strong className="text-slate-100">24.8 Tn · 82.6%</strong></div><div className="mt-2"><Progress value={82.6} tone="sky" label={false} /></div></div><p className="mt-3 text-xs text-amber-200">Próximo mantenimiento en 1,240 km</p></div></section><section><div className="flex items-center justify-between"><h3 className="text-sm font-semibold text-white">Evidencias de entrega</h3><button type="button" onClick={() => onLightbox(0)} className="text-xs font-semibold text-sky-300">Ver galería</button></div><div className="mt-3 grid grid-cols-4 gap-2">{[0,1,2,3].map(index => <button key={index} type="button" onClick={() => onLightbox(index)} className="overflow-hidden rounded-xl border border-white/8 transition hover:border-sky-400/50"><EvidenceTile index={index} className="h-20 w-full" /></button>)}</div></section><section className="rounded-2xl border border-sky-400/18 bg-sky-400/[.055] p-4"><div className="flex gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-xl bg-sky-400/12 text-sky-300"><Bot size={18} /></span><div><p className="font-semibold text-sky-100">Optimización disponible</p><p className="mt-1 text-sm leading-6 text-slate-300">Reorganiza 4 paradas para ahorrar 37 km, 42 min y S/ 186 en combustible.</p><div className="mt-3 flex gap-3"><button type="button" onClick={() => toast.success('Propuesta de ruta abierta.')} className="text-xs font-semibold text-sky-300">Ver propuesta</button><button type="button" onClick={onReplan} className="text-xs font-semibold text-white">Reprogramar</button></div></div></div></section></div> }
function SummaryMetric({label,value,hint,tone}) { return <article className="rounded-2xl border border-white/8 bg-[#0d1626] p-4"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-xl font-semibold tracking-[-.03em] text-white">{value}</p><p className={cx('mt-2 text-xs font-medium', tone==='emerald'?'text-emerald-300':tone==='amber'?'text-amber-300':'text-sky-300')}>{hint}</p></article> }
function DrawerDeliveries({trip}) { return <section><p className="text-sm text-slate-400">{trip.deliveries} entregas procesadas.</p><div className="mt-5 divide-y divide-white/7">{['Grupo Andino · Chimbote','Comercial Pacífico · Nuevo Chimbote','Distribuciones Norte · Virú','Industrias Rivera · Trujillo'].map((name,index) => <div key={name} className="flex items-center gap-3 py-4"><span className={cx('grid size-8 place-items-center rounded-full text-xs font-bold', index < 2 ? 'bg-emerald-400/12 text-emerald-300' : 'bg-white/6 text-slate-400')}>{index < 2 ? <Check size={15} /> : index+3}</span><div className="min-w-0 flex-1"><p className="text-sm font-medium text-slate-200">{name}</p><p className="mt-1 text-xs text-slate-500">{index < 2 ? 'Entregado · POD validado' : 'Próxima ventana de entrega'}</p></div><span className="text-xs text-slate-500">{index < 2 ? `1${index}:2${index}` : 'Pendiente'}</span></div>)}</div></section> }
function DrawerTracking({trip}) { return <section><div className="rounded-2xl border border-white/8 bg-[#0d1626] p-4"><p className="flex items-center gap-2 text-sm font-semibold text-slate-100"><MapPin size={16} className="text-sky-300" />{trip.location}</p><p className="mt-2 text-sm text-slate-400">Actualización GPS recibida {trip.lastUpdate}.</p><div className="mt-4"><Progress value={trip.progress} tone="sky" /></div></div><ol className="mt-6 space-y-5">{[['08:15','Vehículo asignado'],['08:32','Carga completada'],['08:45','Salida del centro logístico'],['10:20','Primera entrega completada'],['11:42',trip.incidents ? 'Alerta de ruta generada' : 'GPS actualizado']].map(([time,event],index) => <li key={time} className="relative flex gap-4"><span className={cx('mt-1.5 size-2.5 rounded-full', index === 4 ? 'bg-sky-400 ring-4 ring-sky-400/12' : 'bg-slate-600')} /><div><p className="text-xs font-semibold text-slate-500">{time}</p><p className="mt-1 text-sm text-slate-200">{event}</p></div></li>)}</ol></section> }
function DrawerDocuments({onLightbox}) { return <section><div className="grid grid-cols-2 gap-3">{[['Guía de remisión','Validada','emerald'],['POD firmado','Validado','emerald'],['Checklist vehículo','Pendiente','amber'],['Foto de carga','4 evidencias','sky']].map(([name,state,tone],index) => <button key={name} type="button" onClick={() => index === 3 ? onLightbox(1) : toast.success(`${name} preparado para revisión.`)} className="rounded-2xl border border-white/8 bg-[#0d1626] p-4 text-left hover:border-white/15"><FileText size={18} className="text-slate-400" /><p className="mt-4 text-sm font-semibold text-slate-100">{name}</p><Chip tone={tone} className="mt-2">{state}</Chip></button>)}</div></section> }
function DrawerIncidents({trip,onIncidence}) { return <section>{trip.incidents ? <div className="rounded-2xl border border-rose-400/18 bg-rose-400/[.055] p-4"><div className="flex items-start gap-3"><CircleAlert className="mt-0.5 text-rose-300" size={19} /><div><p className="font-semibold text-rose-100">{trip.incidents} incidencia{trip.incidents > 1 ? 's' : ''} asociada{trip.incidents > 1 ? 's' : ''}</p><p className="mt-2 text-sm leading-6 text-slate-300">{trip.notes}</p><p className="mt-3 text-xs text-rose-200">Abierta hace {trip.delay === '—' ? '24 min' : trip.delay}</p></div></div></div> : <div className="rounded-2xl border border-emerald-400/18 bg-emerald-400/[.055] p-5 text-center"><CheckCircle2 className="mx-auto text-emerald-300" size={24} /><p className="mt-3 font-semibold text-emerald-100">Sin incidencias activas</p><p className="mt-2 text-sm text-slate-400">La ruta se encuentra dentro de los parámetros esperados.</p></div>}<Button variant="secondary" className="mt-5 w-full" onClick={onIncidence}><Plus size={16} />Registrar nueva incidencia</Button></section> }
function DrawerCosts({trip}) { return <section className="space-y-4"><SummaryMetric label="Costo estimado" value={trip.cost} hint="Presupuesto aprobado" tone="sky" /><SummaryMetric label="Costo actual" value={trip.cost} hint="Variación: +1.8%" tone="amber" /><div className="rounded-2xl border border-white/8 bg-[#0d1626] p-4"><p className="text-sm font-semibold text-slate-100">Combustible</p><p className="mt-2 text-sm text-slate-400">Consumo estimado: 97 L · Desvío presupuestal bajo control.</p></div></section> }

function EvidenceTile({index,className=''}) { const positions = ['0% 0%','50% 0%','100% 0%','0% 100%','50% 100%','100% 100%']; return <span aria-hidden="true" className={cx('block bg-slate-700',className)} style={{backgroundImage:`url(${evidenceSheet})`,backgroundSize:'300% 200%',backgroundPosition:positions[index % positions.length]}} /> }
function Lightbox({index,onClose,onChange}) { const next = () => onChange((index+1)%6); const previous = () => onChange((index+5)%6); return <div className="fixed inset-0 z-[80] grid place-items-center bg-slate-950/90 p-5" role="dialog" aria-modal="true" aria-label="Galería de evidencias"><div className="relative w-full max-w-4xl overflow-hidden rounded-3xl border border-white/12 bg-[#111c2e]"><EvidenceTile index={index} className="aspect-[3/2] w-full" /><div className="absolute inset-x-0 bottom-0 flex items-center justify-between bg-gradient-to-t from-slate-950/90 to-transparent px-5 pb-5 pt-16"><span className="text-sm font-semibold text-white">Evidencia {index+1} de 6</span><span className="text-xs text-slate-300">Registro de demostración</span></div><IconButton label="Cerrar galería" onClick={onClose} className="absolute right-3 top-3 bg-slate-950/70 text-white"><X size={20} /></IconButton><IconButton label="Evidencia anterior" onClick={previous} className="absolute left-3 top-1/2 -translate-y-1/2 bg-slate-950/70 text-white"><ChevronLeft size={22} /></IconButton><IconButton label="Evidencia siguiente" onClick={next} className="absolute right-3 top-1/2 -translate-y-1/2 bg-slate-950/70 text-white"><ChevronRight size={22} /></IconButton></div></div> }

function ModalShell({eyebrow,title,description,onClose,children,footer}) { return <div className="fixed inset-0 z-[70] grid place-items-center bg-slate-950/75 p-4 backdrop-blur-sm" role="presentation"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className="flex max-h-[calc(100vh-2rem)] w-full max-w-3xl flex-col overflow-hidden rounded-3xl border border-white/10 bg-[#111c2e] shadow-2xl"><header className="flex items-start justify-between gap-5 border-b border-white/7 px-6 py-5 sm:px-8"><div><p className="text-xs font-semibold uppercase tracking-[.14em] text-sky-300">{eyebrow}</p><h2 id="modal-title" className="mt-2 text-2xl font-semibold tracking-[-.03em] text-white">{title}</h2><p className="mt-2 text-sm text-slate-400">{description}</p></div><IconButton label="Cerrar formulario" onClick={onClose}><X size={20} /></IconButton></header><div className="min-h-0 flex-1 overflow-y-auto px-6 py-6 sm:px-8">{children}</div>{footer && <footer className="flex items-center justify-end gap-3 border-t border-white/7 bg-[#0d1626] px-6 py-5 sm:px-8">{footer}</footer>}</section></div> }
function Field({label,children,hint,wide=false}) { return <label className={cx('block text-sm font-medium text-slate-300',wide && 'md:col-span-2')}><span>{label}</span>{children}{hint && <span className="mt-1.5 block text-xs leading-5 text-slate-500">{hint}</span>}</label> }
function Input({onChange,...props}) { return <input {...props} onChange={event => onChange?.(event)} className="mt-2 min-h-12 w-full rounded-xl border border-white/8 bg-[#09111f] px-3.5 text-sm text-slate-100 outline-none transition placeholder:text-slate-600 focus:border-sky-400/55 focus:ring-2 focus:ring-sky-400/15" /> }
function Select({children,onChange,...props}) { return <select {...props} onChange={event => onChange?.(event)} className="mt-2 min-h-12 w-full rounded-xl border border-white/8 bg-[#09111f] px-3.5 text-sm text-slate-100 outline-none transition focus:border-sky-400/55 focus:ring-2 focus:ring-sky-400/15">{children}</select> }
function IncidenceModal({onDirty,onClose,onSubmit}) { return <ModalShell eyebrow="OPERACIÓN · RUTA RT-2026-00841" title="Reportar incidencia" description="Registra contexto suficiente para que el centro de operaciones pueda actuar." onClose={onClose} footer={<><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button variant="danger" onClick={onSubmit}><ShieldAlert size={16} />Reportar incidencia</Button></>}><div className="grid gap-x-5 gap-y-5 md:grid-cols-2"><Field label="Tipo de incidencia"><Select onChange={() => onDirty(true)} defaultValue=""><option value="" disabled>Selecciona una opción</option>{['Accidente','Retraso','Problema mecánico','Desvío de ruta','Cliente ausente','Problema documental','Seguridad','Otro'].map(item => <option key={item}>{item}</option>)}</Select></Field><Field label="Severidad"><Select onChange={() => onDirty(true)} defaultValue="Media">{['Baja','Media','Alta','Crítica'].map(item => <option key={item}>{item}</option>)}</Select></Field><Field label="Vehículo"><Input value="TRK-248 · Mercedes Actros" readOnly /></Field><Field label="Conductor"><Input value="Carlos Mendoza" readOnly /></Field><Field label="Descripción" wide hint="Describe qué ocurrió, el impacto y las acciones inmediatas."><textarea onChange={() => onDirty(true)} rows={4} placeholder="Ej.: se detectó congestión extraordinaria en el tramo…" className="mt-2 w-full resize-none rounded-xl border border-white/8 bg-[#09111f] px-3.5 py-3 text-sm text-slate-100 outline-none placeholder:text-slate-600 focus:border-sky-400/55 focus:ring-2 focus:ring-sky-400/15" /></Field><Field label="Ubicación actual"><Input onChange={() => onDirty(true)} defaultValue="Chimbote · km 412" /></Field><Field label="Fecha y hora"><Input onChange={() => onDirty(true)} type="datetime-local" defaultValue="2026-08-30T12:24" /></Field><div className="md:col-span-2"><p className="text-sm font-medium text-slate-300">Evidencia</p><button type="button" onClick={() => onDirty(true)} className="mt-2 flex min-h-28 w-full flex-col items-center justify-center rounded-2xl border border-dashed border-white/15 bg-white/[.025] px-4 text-center transition hover:border-sky-400/45 hover:bg-sky-400/[.04]"><UploadCloud size={22} className="text-sky-300" /><span className="mt-2 text-sm font-semibold text-slate-200">Arrastra imágenes o documentos</span><span className="mt-1 text-xs text-slate-500">JPG, PNG o PDF · máximo 15 MB</span></button></div><label className="md:col-span-2 flex items-start gap-3 rounded-2xl border border-white/8 bg-[#0d1626] p-4"><input type="checkbox" defaultChecked onChange={() => onDirty(true)} className="mt-0.5 size-4 accent-sky-400" /><span><span className="block text-sm font-semibold text-slate-100">Notificar al centro de operaciones</span><span className="mt-1 block text-xs leading-5 text-slate-500">Los responsables recibirán una alerta priorizada y el viaje quedará en seguimiento.</span></span></label></div></ModalShell> }
function ReplanModal({onDirty,onClose,onSubmit}) { return <ModalShell eyebrow="PLANIFICACIÓN · RT-2026-00841" title="Reprogramar ruta" description="El cambio se aplicará después de confirmar el impacto operacional." onClose={onClose} footer={<><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button variant="primary" onClick={onSubmit}>Guardar reprogramación</Button></>}><div className="rounded-2xl border border-amber-400/18 bg-amber-400/[.06] p-4 text-sm text-amber-100"><div className="flex gap-2"><AlertTriangle size={17} className="mt-0.5 shrink-0 text-amber-300" /><p>Esta modificación afectará <b>8 entregas programadas</b>. Los clientes se notificarán solo si confirmas esta operación.</p></div></div><div className="mt-6 grid gap-x-5 gap-y-5 md:grid-cols-2"><Field label="Ruta actual" wide><Input value="Lima → Trujillo · RT-2026-00841" readOnly /></Field><Field label="Nueva fecha"><Input type="date" onChange={() => onDirty(true)} defaultValue="2026-08-30" /></Field><Field label="Nueva hora"><Input type="time" onChange={() => onDirty(true)} defaultValue="09:30" /></Field><Field label="Nuevo vehículo"><Select onChange={() => onDirty(true)} defaultValue="TRK-248"><option>TRK-248 · Mercedes Actros</option><option>TRK-317 · Volvo FMX</option><option>TRK-401 · Scania R450</option></Select></Field><Field label="Nuevo conductor"><Select onChange={() => onDirty(true)} defaultValue="Carlos Mendoza"><option>Carlos Mendoza</option><option>Lucía Paredes</option><option>Jorge Salas</option></Select></Field><Field label="Motivo" wide><textarea rows={3} onChange={() => onDirty(true)} placeholder="Indica el motivo de la reprogramación" className="mt-2 w-full resize-none rounded-xl border border-white/8 bg-[#09111f] px-3.5 py-3 text-sm text-slate-100 outline-none placeholder:text-slate-600 focus:border-sky-400/55" /></Field><label className="md:col-span-2 flex items-start gap-3 rounded-2xl border border-white/8 bg-[#0d1626] p-4"><input type="checkbox" defaultChecked onChange={() => onDirty(true)} className="mt-0.5 size-4 accent-sky-400" /><span><span className="block text-sm font-semibold text-slate-100">Notificar automáticamente a clientes afectados</span><span className="mt-1 block text-xs text-slate-500">La notificación incluirá la nueva ventana estimada de entrega.</span></span></label></div></ModalShell> }
function ConfirmDialog({item,onCancel,onConfirm}) { const discard = item.type === 'discard'; return <div className="fixed inset-0 z-[75] grid place-items-center bg-slate-950/75 p-4" role="presentation"><section role="alertdialog" aria-modal="true" className="w-full max-w-md rounded-3xl border border-white/10 bg-[#172235] p-6 shadow-2xl"><span className={cx('grid size-11 place-items-center rounded-2xl', discard ? 'bg-amber-400/12 text-amber-300' : 'bg-sky-400/12 text-sky-300')}>{discard ? <AlertTriangle size={21} /> : <Sparkles size={21} />}</span><h2 className="mt-5 text-xl font-semibold text-white">{discard ? 'Tienes cambios sin guardar' : 'Aplicar optimización'}</h2><p className="mt-2 text-sm leading-6 text-slate-400">{discard ? 'Si cierras ahora, perderás la información registrada en el formulario.' : 'La propuesta reorganizará 4 paradas. Ahorrarás 37 km, 42 minutos y S/ 186. Esta decisión requiere tu confirmación.'}</p><div className="mt-6 flex justify-end gap-3"><Button variant="secondary" onClick={onCancel}>{discard ? 'Seguir editando' : 'Cancelar'}</Button><Button variant={discard ? 'danger' : 'primary'} onClick={onConfirm}>{discard ? 'Salir sin guardar' : 'Aplicar optimización'}</Button></div></section></div> }

function CommandPalette({query,setQuery,onClose,onOpenTrip,onIncidence}) { const commands = [{label:'Buscar ruta RT-2026-00841',hint:'Ruta',action:() => onOpenTrip(TRIPS[0])},{label:'Ver vehículo TRK-284',hint:'Flota',action:() => onOpenTrip(TRIPS[1])},{label:'Crear incidencia',hint:'Acción',action:onIncidence},{label:'Planificar nueva ruta',hint:'Acción',action:() => toast.success('Planificador abierto en modo demo.')},{label:'Abrir entregas pendientes',hint:'Entrega',action:() => onOpenTrip(TRIPS[3])}].filter(item => item.label.toLowerCase().includes(query.toLowerCase())); return <div className="fixed inset-0 z-[90] flex items-start justify-center bg-slate-950/70 px-4 pt-[12vh] backdrop-blur-sm" onMouseDown={event => { if(event.target === event.currentTarget) onClose() }} role="presentation"><section role="dialog" aria-modal="true" aria-label="Paleta de comandos" className="w-full max-w-2xl overflow-hidden rounded-3xl border border-white/12 bg-[#172235] shadow-2xl"><label className="flex items-center gap-3 border-b border-white/8 px-5 py-4"><Command size={20} className="text-sky-300" /><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="Busca una ruta, vehículo, conductor o acción…" className="min-w-0 flex-1 bg-transparent text-base text-white outline-none placeholder:text-slate-500" /><kbd className="rounded border border-white/10 px-1.5 py-0.5 text-xs text-slate-500">ESC</kbd></label><div className="p-2"><p className="px-3 py-2 text-[11px] font-semibold uppercase tracking-[.12em] text-slate-500">Acciones rápidas</p>{commands.map(item => <button key={item.label} type="button" onClick={item.action} className="flex w-full items-center justify-between rounded-xl px-3 py-3 text-left hover:bg-white/7"><span className="flex items-center gap-3 text-sm font-medium text-slate-100"><Search size={16} className="text-slate-500" />{item.label}</span><span className="rounded bg-white/6 px-2 py-1 text-[10px] text-slate-400">{item.hint}</span></button>)}{!commands.length && <p className="px-3 py-8 text-center text-sm text-slate-500">No encontramos resultados para esta búsqueda.</p>}</div><div className="border-t border-white/8 px-5 py-3 text-xs text-slate-500"><kbd className="mr-1 rounded border border-white/10 px-1">↑↓</kbd> navegar <kbd className="ml-3 mr-1 rounded border border-white/10 px-1">↵</kbd> seleccionar</div></section></div> }

function OfflineNotice({onRetry}) { return <div role="status" className="mb-5 flex flex-wrap items-center gap-3 rounded-2xl border border-amber-400/18 bg-amber-400/[.06] px-4 py-3.5"><WifiOff size={18} className="text-amber-300" /><p className="flex-1 text-sm text-amber-100"><b>Conexión perdida.</b> Mostrando los últimos datos sincronizados a las 14:32:18.</p><button type="button" onClick={onRetry} className="text-sm font-semibold text-amber-200 hover:text-white">Reintentar</button></div> }
function LoadingState() { return <div aria-label="Cargando Control Tower" className="animate-pulse"><div className="h-7 w-48 rounded-lg bg-white/8" /><div className="mt-4 h-5 w-96 max-w-full rounded-lg bg-white/6" /><div className="mt-8 grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{Array.from({length:6},(_,i) => <div key={i} className="h-36 rounded-2xl border border-white/6 bg-white/[.035]" />)}</div><div className="mt-6 grid gap-5 xl:grid-cols-[1.6fr_.72fr]"><div className="h-[510px] rounded-2xl border border-white/6 bg-white/[.035]" /><div className="h-[510px] rounded-2xl border border-white/6 bg-white/[.035]" /></div><div className="mt-6 h-80 rounded-2xl border border-white/6 bg-white/[.035]" /></div> }
function ErrorState({onRetry}) { return <section className="mx-auto mt-[15vh] max-w-xl rounded-3xl border border-rose-400/16 bg-[#111c2e] px-8 py-12 text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-rose-400/12 text-rose-300"><WifiOff size={26} /></span><h1 className="mt-5 text-2xl font-semibold text-white">No pudimos cargar las rutas</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-slate-400">Revisa tu conexión o vuelve a intentarlo. Tus filtros permanecerán disponibles al recuperar los datos.</p><Button variant="primary" className="mt-6" onClick={onRetry}><RefreshCw size={16} />Reintentar</Button></section> }

createRoot(document.getElementById('root')).render(<App />)
